CREATE_NEW_CONSOLE = 0x00000010
CREATE_NEW_PROCESS_GROUP = 0x00000200
DEFAULT_TIMEOUT_S = 120.0   # run() без своего таймаута не висит часами (сирота ssh/git); по таймауту процесс убит


